  "check_code": """"Deterministic post-state checks for the Asana mutation task."""

import sqlite3
from pathlib import Path


TARGET_TASK_ID = "TASK-ONE-2025-231"
TARGET_INITIATIVES = ("INIT-BNS-2025-ONE-02", "INIT-BNS-2025-OSW-03")


def _db(workspace):
    return Path(workspace).resolve().parent / "system" / "asana_steering_portfolio" / "state.db"


def _pinned_db(workspace):
    return Path(workspace).resolve().parent / "system" / "asana_steering_portfolio" / "state.db.pinned_backup"


def _row(con, task_id):
    row = con.execute("SELECT * FROM workstream_tasks WHERE task_id = ?", (task_id,)).fetchone()
    return dict(row) if row else None


def check_oneida_notice_task_poststate(workspace):
    expected = {
        "task_status": "IN_PROGRESS",
        "owner_person_id": "PERSON_HELEN_WU",
        "due_date": "2026-01-09",
        "dependency_task_id": "TASK-ONE-2025-214",
        "dependency_review_status": "SATISFIED",
        "closure_case_id": "SN-CLSR-2025-ONE-0042",
        "completed_at": None,
        "work_product_code": "ONE_NOTICE_PACKAGE",
        "notes": "Package must include detailed reasons and supporting statistics; task completion will not record regulator approval.",
    }
    with sqlite3.connect(_db(workspace)) as con:
        con.row_factory = sqlite3.Row
        actual = _row(con, TARGET_TASK_ID)
    if actual is None:
        return {"score": 0, "detail": "Target task TASK-ONE-2025-231 is missing."}
    mismatches = {key: (actual.get(key), value) for key, value in expected.items() if actual.get(key) != value}
    if mismatches:
        return {"score": 0, "detail": f"Target post-state mismatch: {mismatches}"}
    return {"score": 1, "detail": "Oneida notice-package task is IN_PROGRESS with required metadata preserved."}


def check_unrelated_oneida_oswego_unchanged(workspace):
    current_path = _db(workspace)
    pinned_path = _pinned_db(workspace)
    columns = [
        "task_id", "initiative_id", "location_id", "task_name", "task_category",
        "owner_person_id", "closure_case_id", "legacy_intake_reference", "work_product_code",
        "task_status", "due_date", "completed_at", "dependency_task_id",
        "dependency_review_status", "notes", "created_at", "updated_at",
    ]
    select = ", ".join(columns)
    with sqlite3.connect(current_path) as current, sqlite3.connect(pinned_path) as pinned:
        current.row_factory = sqlite3.Row
        pinned.row_factory = sqlite3.Row
        current_rows = {
            row["task_id"]: dict(row)
            for row in current.execute(
                "SELECT " + select + " FROM workstream_tasks WHERE initiative_id IN (?, ?)",
                TARGET_INITIATIVES,
            )
            if row["task_id"] != TARGET_TASK_ID
        }
        pinned_rows = {
            row["task_id"]: dict(row)
            for row in pinned.execute(
                "SELECT " + select + " FROM workstream_tasks WHERE initiative_id IN (?, ?)",
                TARGET_INITIATIVES,
            )
            if row["task_id"] != TARGET_TASK_ID
        }
    if current_rows != pinned_rows:
        changed = sorted(set(current_rows) | set(pinned_rows))
        details = [task_id for task_id in changed if current_rows.get(task_id) != pinned_rows.get(task_id)]
        return {"score": 0, "detail": f"Unrelated Oneida/Oswego tasks changed: {details}"}
    return {"score": 1, "detail": "All other Oneida and Oswego workstreams remain unchanged."}
